<template><div class="space-y-5"><NuxtLink to="/recipes" class="text-red-800">← My Recipes</NuxtLink><p v-if="error" class="error">{{error}}</p><p v-else-if="loading">Loading…</p><template v-else-if="data"><div class="flex justify-between items-center gap-3"><h1 class="text-3xl font-bold">{{data.recipe.title}}</h1><NuxtLink class="btn btn-secondary" :to="`/recipes/${id}/edit`">Edit</NuxtLink></div><img v-if="image" :src="image" :alt="data.recipe.title" class="rounded-xl max-h-80 object-cover"/><p class="text-stone-600">{{data.recipe.description}}</p><p class="text-sm">{{data.recipe.category}} · Serves {{data.recipe.servings}} · Prep {{data.recipe.prep_minutes}} min · Cook {{data.recipe.cook_minutes}} min</p><div class="grid md:grid-cols-2 gap-5"><section class="card"><h2 class="text-xl font-bold mb-3">Ingredients</h2><ul class="list-disc pl-5 space-y-2"><li v-for="x in data.ingredients" :key="x.id">{{x.quantity??''}} {{x.unit}} {{x.name}} {{x.notes}}</li></ul></section><section class="card"><h2 class="text-xl font-bold mb-3">Instructions</h2><ol class="list-decimal pl-5 space-y-3"><li v-for="s in data.steps" :key="s.id">{{s.instruction}}</li></ol></section></div><button class="btn btn-secondary" @click="remove">Delete Recipe</button></template></div></template>
<script setup lang="ts">
definePageMeta({middleware:'auth'});const id=String(useRoute().params.id),repo=useRecipeRepository();const data=ref<Awaited<ReturnType<typeof repo.get>>|null>(null),image=ref(''),error=ref(''),loading=ref(true)
onMounted(async()=>{try{data.value=await repo.get(id);if(data.value.recipe.cover_image_path)image.value=await repo.imageUrl(data.value.recipe.cover_image_path)}catch(e:any){error.value=e.message||'Recipe unavailable'}finally{loading.value=false}})
async function remove(){if(!confirm('Permanently delete this recipe?'))return;try{await repo.remove(id);await navigateTo('/recipes')}catch(e:any){error.value=e.message||'Unable to delete'}}
</script>
